import{_ as t,o as u,c as e,ag as q}from"./chunks/framework.B5ULsuav.js";const p=JSON.parse('{"title":"金刚经金句","description":"","frontmatter":{},"headers":[],"relativePath":"40-原话金句/quote-金刚经.md","filePath":"40-原话金句/quote-金刚经.md","lastUpdated":1778155802000}'),r={name:"40-原话金句/quote-金刚经.md"};function a(l,o,c,n,s,b){return u(),e("div",null,[...o[0]||(o[0]=[q('<h1 id="金刚经金句" tabindex="-1">金刚经金句 <a class="header-anchor" href="#金刚经金句" aria-label="Permalink to &quot;金刚经金句&quot;">​</a></h1><blockquote><p>了空居士讲解《金刚经》精彩原话集</p></blockquote><hr><h2 id="一、心法总纲" tabindex="-1">一、心法总纲 <a class="header-anchor" href="#一、心法总纲" aria-label="Permalink to &quot;一、心法总纲&quot;">​</a></h2><blockquote><p><strong>&quot;保持平静的要诀就是保持理智地去看待一切。不平静的时候问自己：&#39;我为什么要不平静？这样的不平静正确吗？&#39;&quot;</strong></p></blockquote><blockquote><p><strong>&quot;过去心不可得，现在心不可得，未来心不可得。过去已成过去，未来还没有来，现在却不断地在流动。&quot;</strong></p></blockquote><blockquote><p><strong>&quot;若见诸相非相，即见如来——看到一切现象都不是永恒的，你就见到真相了。&quot;</strong></p></blockquote><blockquote><p><strong>&quot;凡所有相，皆是虚妄。不是没有相，而是说所有的相都是假的、不永恒的，你不要被它骗了。&quot;</strong></p></blockquote><blockquote><p><strong>&quot;应无所住而生其心——心不要停在任何一个地方，不停留才能生出真正的智慧。&quot;</strong></p></blockquote><hr><h2 id="二、对境不住" tabindex="-1">二、对境不住 <a class="header-anchor" href="#二、对境不住" aria-label="Permalink to &quot;二、对境不住&quot;">​</a></h2><blockquote><p><strong>&quot;不平静时问自己：&#39;我为什么要不平静？这样正确吗？&#39;——你一问，心就静下来了。&quot;</strong></p></blockquote><blockquote><p><strong>&quot;知见无见，斯即涅槃——知道各种观点，但内心不执着于任何观点，这就是涅槃。&quot;</strong></p></blockquote><blockquote><p><strong>&quot;要无住生心——该住就住，不该住就不住。吃饭就是吃饭，睡觉就是睡觉，不要一边吃饭一边想昨天的事。&quot;</strong></p></blockquote><blockquote><p><strong>&quot;过去心不可得，不是说不要回忆过去，而是不要被过去绑住。你回忆一下没问题，问题是你回忆的时候心在不在当下。&quot;</strong></p></blockquote><hr><h2 id="三、对法不执" tabindex="-1">三、对法不执 <a class="header-anchor" href="#三、对法不执" aria-label="Permalink to &quot;三、对法不执&quot;">​</a></h2><blockquote><p><strong>&quot;法尚应舍，何况非法——连佛法都要放下，何况那些不是法的东西。法是指南针，不是终点。&quot;</strong></p></blockquote><blockquote><p><strong>&quot;所谓佛法者，即非佛法——佛祖说的种种方法是对症下药，药方不能通用。不要将佛祖对甲说的话拿去给乙用。&quot;</strong></p></blockquote><blockquote><p><strong>&quot;无有定法名阿耨多罗三藐三菩提，亦无有定法如来可说——没有一个固定的方法叫做开悟。&quot;</strong></p></blockquote><blockquote><p><strong>&quot;庄严佛土者，即非庄严，是名庄严——做了一件好事，心里没有&#39;我在做好事&#39;的念头，这才是真正的庄严。&quot;</strong></p></blockquote><blockquote><p><strong>&quot;实无有法名阿罗汉——不觉得自己证得了什么，才是真正的证得。&quot;</strong></p></blockquote><blockquote><p><strong>&quot;法无定法，各人因缘不同。千万不要拿自己的法门去评判别人的。&quot;</strong></p></blockquote><hr><h2 id="四、自然务实" tabindex="-1">四、自然务实 <a class="header-anchor" href="#四、自然务实" aria-label="Permalink to &quot;四、自然务实&quot;">​</a></h2><blockquote><p><strong>&quot;一切贤圣，皆以无为法而有差别——方法有快慢，但都是为了到彼岸。坐飞机和走路都能到北京。&quot;</strong></p></blockquote><blockquote><p><strong>&quot;如来所说三千大千世界，即非世界，是名世界——名字只是个标签，不要被名字骗了。说来说去，你还是要实际去做。&quot;</strong></p></blockquote><blockquote><p><strong>&quot;信心不逆——真正相信了《金刚经》的道理，在做事时就会自觉&#39;以无我无人修一切善法&#39;。知行合一才是真信。&quot;</strong></p></blockquote><blockquote><p><strong>&quot;以无我无人无众生无寿者修一切善法，即得阿耨多罗三藐三菩提——不是先成佛再行善，而行善的同时就符合了成佛的标准。&quot;</strong></p></blockquote><hr><h2 id="五、圆融中和" tabindex="-1">五、圆融中和 <a class="header-anchor" href="#五、圆融中和" aria-label="Permalink to &quot;五、圆融中和&quot;">​</a></h2><blockquote><p><strong>&quot;是故不应取法，不应取非法——不能执着于方法，也不能执着于&#39;一切都是空的&#39;。吃药好了就不吃了，病没好也不能不吃。&quot;</strong></p></blockquote><blockquote><p><strong>&quot;如来所说法，皆不可取，不可说——不要一听到什么就去抓住它，也不要一听到什么就说它不对。要具体问题具体分析。&quot;</strong></p></blockquote><blockquote><p><strong>&quot;若作是言：&#39;我当灭度无量众生&#39;，即不名菩萨——觉得自己&#39;度了很多人&#39;，那就还不是菩萨。度众生是分内之事，像父母养小孩一样自然。&quot;</strong></p></blockquote><hr><h2 id="六、历境炼心" tabindex="-1">六、历境炼心 <a class="header-anchor" href="#六、历境炼心" aria-label="Permalink to &quot;六、历境炼心&quot;">​</a></h2><blockquote><p><strong>&quot;一切法皆是佛法——不是做好事和做坏事没有区别，而是说只要不执着，一切现象都能成为觉悟的契机。&quot;</strong></p></blockquote><blockquote><p><strong>&quot;烦恼即菩提——烦恼不是敌人，它是你修行的机会。每一次烦恼来的时候，就是你进步的契机。&quot;</strong></p></blockquote><blockquote><p><strong>&quot;若复有人得闻是经，不惊不怖不畏——听到《金刚经》的道理不害怕，这个人就有大根器。因为这是要放下一切的。&quot;</strong></p></blockquote><hr><h2 id="七、天人合一与性命双修" tabindex="-1">七、天人合一与性命双修 <a class="header-anchor" href="#七、天人合一与性命双修" aria-label="Permalink to &quot;七、天人合一与性命双修&quot;">​</a></h2><blockquote><p><strong>&quot;佛说非身，是名大身——真正的&#39;大&#39;是跟宇宙一样大，你与万物为一体的那种大。&quot;</strong></p></blockquote><blockquote><p><strong>&quot;一滴水与大海融为一体——到底是大海得到一滴水，还是一滴水得到了大海？这就是一体。&quot;</strong></p></blockquote><blockquote><p><strong>&quot;若菩萨通达无我法者，如来说名真是菩萨——通达无我，做事都是自然流露，不图功德相，但也不是什么都不做。&quot;</strong></p></blockquote><hr><h2 id="八、简短金句-适合随时提醒" tabindex="-1">八、简短金句（适合随时提醒） <a class="header-anchor" href="#八、简短金句-适合随时提醒" aria-label="Permalink to &quot;八、简短金句（适合随时提醒）&quot;">​</a></h2><blockquote><p>&quot;做就是了。&quot;</p></blockquote><blockquote><p>&quot;不怕念起，只怕觉迟。&quot;</p></blockquote><blockquote><p>&quot;保持平静。&quot;</p></blockquote><blockquote><p>&quot;用心但不执着。&quot;</p></blockquote><blockquote><p>&quot;当下即是。&quot;</p></blockquote><hr><blockquote><p>来源：<a href="/liaokongjushi-wisdom/01-Raw-Sources/1了空居士讲《金刚经》-第一分法会因由分20160909">1了空居士讲《金刚经》-第一分法会因由分20160909</a> 至 <a href="/liaokongjushi-wisdom/01-Raw-Sources/32了空居士讲《金刚经》-第三十二分应化非真分20170609">32了空居士讲《金刚经》-第三十二分应化非真分20170609</a> 整理日期：2026-05-06</p></blockquote>',53)])])}const g=t(r,[["render",a]]);export{p as __pageData,g as default};
